"""Flashcards: (tag, question, answer). Built from the lab templates and the template-anatomy handout."""

CARDS = [
    ("sections", "Which template section is the ONLY required one?", "Resources. Everything else (Description, Metadata, Parameters, Rules, Mappings, Conditions, Transform, Outputs) is optional."),
    ("sections", "Name the 10 top-level template sections.", "AWSTemplateFormatVersion, Description, Metadata, Parameters, Rules, Mappings, Conditions, Transform, Resources, Outputs."),
    ("sections", "What is AWSTemplateFormatVersion for? What value?", "Identifies the template format version (NOT a deployment date). Only supported value: '2010-09-09'."),
    ("sections", "What does the Rules section do?", "Validates combinations of parameter values BEFORE resources are created (e.g. if Environment is prod, instance size must be an approved prod size)."),
    ("sections", "What does Metadata with AWS::CloudFormation::Interface do?", "Only changes how parameters are grouped/labelled on the console input screen. Creates nothing."),
    ("sections", "What is Transform used for?", "Names a macro/transform (e.g. AWS::Serverless-2016-10-31 = SAM) that expands shorthand into normal CloudFormation before creation."),
    ("sections", "Template size/limits worth knowing?", "51,200 bytes when pasted/uploaded directly, 1 MB from S3; max 500 resources, 200 parameters, 200 outputs per template."),

    ("functions", "Write: reference the security group 'Allowhttp' ID for use in an instance in a NON-default VPC.", "SecurityGroupIds:\n  - !GetAtt Allowhttp.GroupId\n(SecurityGroups with !Ref only works in the default VPC.)"),
    ("functions", "!Ref on a resource returns...? On a parameter?", "Resource: usually its physical id (instance id, VPC id, subnet id). EXCEPTION: AWS::EC2::SecurityGroup returns the group ID only if VpcId is set - with no VpcId (default VPC) it returns the group NAME; use !GetAtt SG.GroupId for the ID. Parameter: the value supplied."),
    ("functions", "Write: public IP of instance 'Web' for an Output.", "Value: !GetAtt Web.PublicIp   (private: Web.PrivateIp, id: !Ref Web)"),
    ("functions", "Write: first AZ in the current region.", "!Select [0, !GetAZs \"\"]   (second AZ = index 1)"),
    ("functions", "Write the long form of !GetAtt Web.PublicIp.", "Fn::GetAtt: [Web, PublicIp]"),
    ("functions", "!Sub - what is it and what pseudo-params can you use?", "String substitution: 'http://${Web.PublicIp}' or '${AWS::StackName}'. Pseudo-parameters: AWS::Region, AWS::StackName, AWS::StackId, AWS::AccountId, AWS::Partition, AWS::URLSuffix, AWS::NotificationARNs, AWS::NoValue."),
    ("functions", "In UserData with !Sub, how do you write a literal bash ${HOME}?", "${!HOME}  - the ! escapes it so Sub leaves it as ${HOME}. (Plain $VAR without braces is fine.)"),
    ("functions", "Why do the labs write 'Fn::Base64: !Sub |' instead of '!Base64 !Sub |'?", "YAML can't put two tags on one value, so a short-form function can't take ANOTHER short-form function as its whole value (!Base64 !Sub ... is invalid). Use the full name for at least one: Fn::Base64: !Sub |. Short forms inside lists are fine, e.g. !Select [0, !GetAZs \"\"]."),
    ("functions", "Write: pick an AMI from a Mapping called RegionMap keyed by region, attribute AMI.", "ImageId: !FindInMap [RegionMap, !Ref 'AWS::Region', AMI]"),
    ("functions", "Write: size t2.small in prod else the parameter value.", "InstanceType: !If [IsProd, t2.small, !Ref InstanceType]"),
    ("functions", "What does !Ref 'AWS::NoValue' do inside !If?", "Removes the property entirely when that branch is chosen."),
    ("functions", "Write: join 'a' and 'b' with a dash.", "!Join ['-', [a, b]]"),
    ("functions", "Write a Condition that is true when Environment is prod.", "Conditions:\n  IsProd: !Equals [!Ref Environment, prod]"),
    ("functions", "Condition functions available?", "Fn::And, Fn::Equals, Fn::If, Fn::Not, Fn::Or."),
    ("functions", "What does !Cidr do?", "Splits a CIDR into subnets: !Cidr [!GetAtt VPC.CidrBlock, 4, 8] -> 4 blocks with 8 host bits (/24 in a /16). Pair with !Select."),
    ("functions", "How do you create a resource only when a condition is true?", "Add 'Condition: IsProd' at the resource level (same indent as Type). Outputs that use it need the same Condition."),

    ("params", "Parameter type that gives a key pair dropdown?", "AWS::EC2::KeyPair::KeyName"),
    ("params", "Parameter type that pulls the latest AMI id from SSM?", "AWS::SSM::Parameter::Value<AWS::EC2::Image::Id> with Default /aws/service/ami-amazon-linux-latest/al2023-ami-kernel-default-x86_64"),
    ("params", "List the parameter constraint keywords.", "AllowedValues, AllowedPattern, MinLength, MaxLength, MinValue, MaxValue (plus ConstraintDescription for the error message). Other parameter properties: Type, Default, Description, NoEcho."),
    ("params", "What does NoEcho do - and not do?", "Masks the value (****) in console/describe calls. It is NOT secure storage; secrets still end up in templates/UserData/outputs if you put them there. Use Secrets Manager / SSM SecureString."),
    ("params", "A regex AllowedPattern for 'IPv4 followed by /32'?", "'(\\d{1,3}\\.){3}\\d{1,3}/32'"),
    ("params", "Parameter Default must satisfy what?", "Its own AllowedValues / AllowedPattern / min-max, or the stack fails validation (cfn-lint E2015)."),

    ("network", "Resources needed to make a subnet public?", "IGW + VPCGatewayAttachment, RouteTable with 0.0.0.0/0 -> IGW (Route), SubnetRouteTableAssociation. MapPublicIpOnLaunch: true auto-assigns public IPs."),
    ("network", "Why does AWS::EC2::Route often have DependsOn: InternetGatewayAttachment?", "The route needs the IGW attached to the VPC first; the Ref to the IGW alone does not guarantee the attachment is finished."),
    ("network", "Where does a NAT gateway live and what does it need?", "In a PUBLIC subnet, with an Elastic IP: AllocationId: !GetAtt Eip.AllocationId. The PRIVATE route table gets 0.0.0.0/0 with NatGatewayId."),
    ("network", "EIP in a VPC: which property?", "Domain: vpc"),
    ("network", "Subnet CIDR rules?", "Must sit inside the VPC CIDR and must not overlap other subnets. AWS reserves 5 addresses per subnet. e.g. 192.168.1.0/24 inside 192.168.0.0/16."),
    ("network", "EnableDnsHostnames / EnableDnsSupport - what for?", "Instances get public DNS names / DNS resolution works inside the VPC. Set both true on the VPC."),
    ("network", "A route table is created but traffic doesn't flow - first check?", "Is it ASSOCIATED to the subnet (SubnetRouteTableAssociation)? Unassociated subnets use the VPC's main route table."),
    ("network", "SG rule: allow from another security group instead of a CIDR?", "SourceSecurityGroupId: !GetAtt OtherSG.GroupId"),
    ("network", "Two SGs reference each other and you get 'Circular dependency'. Fix?", "Move the cross rules into standalone AWS::EC2::SecurityGroupIngress resources (as in the Ansible lab template)."),
    ("network", "SecurityGroupIngress IpProtocol value for all traffic?", "'-1' (quoted)."),

    ("deps", "What creates an implicit dependency?", "Any !Ref, !GetAtt or ${Resource} inside !Sub pointing at another resource."),
    ("deps", "When do you need explicit DependsOn?", "When there's no reference but order matters (route needs IGW attachment, EC2 needs route + association before UserData needs internet, WaitCondition after instance)."),
    ("deps", "Instance 2 sits in subnet 2. Which association should it DependsOn?", "RouteTableAssociationPublic2 (its OWN subnet). The lab file mistakenly pointed at association 1."),

    ("init", "Where does AWS::CloudFormation::Init go?", "Under the EC2 resource's Metadata (sibling of Properties). cfn-init in UserData reads it."),
    ("init", "Order cfn-init runs config keys?", "packages, groups, users, sources, files, commands, services. Within commands, keys run in alphabetical order (hence 01_, 02_)."),
    ("init", "WaitCondition properties?", "Handle (!Ref the WaitConditionHandle), Timeout (seconds, string), Count (number of success signals). Add DependsOn: the instance."),
    ("init", "How does the instance signal success?", "/opt/aws/bin/cfn-signal -e $? --id <id> '${MyWaitHandle}'  ($? = exit code of cfn-init, 0 = success). Alternative: CreationPolicy with ResourceSignal."),
    ("init", "Which package provides cfn-init/cfn-signal on AL2023?", "aws-cfn-bootstrap (dnf install -y aws-cfn-bootstrap)."),

    ("stacks", "Outputs: how do you export and import across stacks?", "Export: Name: !Sub '${AWS::StackName}-VPCId'. Import: Fn::ImportValue: !Sub '${NetworkStackName}-VPCId'. Export names unique per region/account; can't delete a stack whose exports are in use."),
    ("stacks", "Stack in ROLLBACK_COMPLETE - what now?", "Open Events, find the OLDEST *_FAILED event for the real reason, fix the template, DELETE the stack, create again (rolled-back creates can't be updated)."),
    ("stacks", "Update behaviours?", "No interruption, Some interruption, Replacement (new physical resource, old deleted). Preview with a change set."),
    ("stacks", "Drift detection?", "Compares live resources with the template to find manual out-of-band changes."),
    ("stacks", "DeletionPolicy values?", "Delete (default for most resources), Retain, RetainExceptOnCreate, Snapshot (only some types, e.g. AWS::EC2::Volume, AWS::RDS::DBInstance/DBCluster). UpdateReplacePolicy covers replacement during updates."),
    ("stacks", "When is --capabilities CAPABILITY_IAM needed?", "When the template creates IAM resources (CAPABILITY_NAMED_IAM if you name them)."),
    ("stacks", "CLI: create, validate, delete, inspect events?", "aws cloudformation create-stack --stack-name X --template-body file://t.yaml --parameters ParameterKey=K,ParameterValue=V | validate-template | delete-stack | describe-stack-events | deploy (create-or-update)."),

    ("yaml", "YAML rules that bite in CloudFormation?", "Spaces only (no tabs); consistent indentation; '- ' for lists; quote strings that look like numbers/booleans/versions ('2010-09-09', '300'); '|' keeps newlines for UserData."),
    ("yaml", "Short vs long intrinsic form?", "!Ref X == Ref: X ; !GetAtt A.B == Fn::GetAtt: [A, B]; !Sub == Fn::Sub. A short form can't directly take another short form as its whole value (!Base64 !Sub); inside lists it's fine (!Select [0, !GetAZs \"\"])."),
    ("yaml", "Why is Timeout written '300' with quotes in the lab?", "CloudFormation expects a String there; quoting keeps YAML from turning it into an int (both usually work, quoting is the documented form)."),

    ("lab", "AWS Academy key pair name used in the labs?", "vockey"),
    ("lab", "Can you create IAM roles in the AWS Academy Learner Lab?", "Reportedly no - creating IAM roles/policies/instance profiles is blocked. Use the pre-made LabRole (check your lab for the matching instance profile name). Confirm in your own lab before the exam."),
    ("lab", "Why must AMI ids be region-specific, and how to avoid hard-coding?", "AMI ids differ per region. Use a Mapping keyed by AWS::Region, or an SSM public parameter (AWS::SSM::Parameter::Value<AWS::EC2::Image::Id>)."),
    ("lab", "Typical exam time-sink and how to avoid it?", "Fixing a broken base template last-minute. Get the base deploying first, then add complexity one small piece at a time, redeploying each time."),
]
